from itertools import combinations, product


def _route(data, minimum_duration, exact):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    initial_mask = bit.get(source, 0)
    budget = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    initial = (source, initial_mask, 0)
    distances = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if node == target and mask == full and (not exact or used == budget):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < budget:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_route(minimum_duration, exact):
    return lambda data: _route(data, minimum_duration, exact)


def _round(numerator, denominator, mode):
    quotient, remainder = divmod(numerator, denominator)
    if mode == "half_up" and remainder * 2 >= denominator:
        quotient += 1
    return quotient


def _ledger(data):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, data["rounding"])
        tax = _round(net * event.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    rows_by_version = {}
    for name in names:
        versions = {}
        for row in packages[name]:
            versions[row["version"]] = row
        rows_by_version[name] = versions
        allowed = [-1] + [v for v in versions
                          if v not in blocked.get(name, [])
                          and (name not in pins or pins[name] == v)]
        choices.append(allowed)

    best_vector = None
    best_versions = None
    for vector in product(*choices):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        if any(name not in installed or not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue

        adjacency = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = rows_by_version[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in installed or not dep["min"] <= installed[other] <= dep["max"]:
                    valid = False
                    break
                adjacency[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in installed:
                valid = False
                break
            reachable.add(name)
            stack.extend(adjacency[name])
        if not valid or reachable != set(installed):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in adjacency[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in adjacency):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = installed

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for selected in combinations(options, k):
        ids = [job["id"] for job in selected]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        ordered = sorted(selected, key=lambda job: (job["start"], job["end"], job["id"]))
        active_ends = []
        feasible = True
        for job in ordered:
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in selected)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value = value
            best_ids = sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


